        if(stage==2){var p=ManeuverClient.current();if(p==null||p.nodes().size()!=1)return;var fields=mc.screen.children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).toList();require(fields.size()==5,"Planner axis fields missing");fields.get(0).setValue("25");fields.get(1).setValue("-5");fields.get(2).setValue("10");fields.get(3).setValue("40000,15");fields.get(4).setValue("20000");chooseTarget((OrbitMapScreen)mc.screen);stage=3;at=ticks;return;}
