    private static boolean clickApproach(OrbitMapScreen screen){try{var layer=rendezvous(screen);var f=layer.getClass().getDeclaredField("prediction");f.setAccessible(true);var prediction=(RendezvousMath.Prediction)f.get(layer);if(prediction==null)return false;f=layer.getClass().getDeclaredField("predictionHash");f.setAccessible(true);if(f.getInt(layer)!=ManeuverClient.current().nodes().hashCode())return false;var visible=OrbitMapScreen.class.getDeclaredMethod("visible",SpaceVector.class);visible.setAccessible(true);for(var a:prediction.approaches()){if(a.tick()<=ManeuverClient.now()+40||!(Boolean)visible.invoke(screen,a.own().position()))continue;var xy=project(screen,a.own().position());approachTick=a.tick();screen.mouseClicked(xy.x(),xy.y(),0);screen.mouseReleased(xy.x(),xy.y(),0);return true;}return false;}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
