    private static void checkSpaceWeather(Minecraft mc){
        var thunder=net.minecraft.client.resources.sounds.SimpleSoundInstance.forUI(net.minecraft.sounds.SoundEvents.LIGHTNING_BOLT_THUNDER,1);
        var click=net.minecraft.client.resources.sounds.SimpleSoundInstance.forUI(net.minecraft.sounds.SoundEvents.UI_BUTTON_CLICK,1);
        var weather=new net.neoforged.neoforge.client.event.sound.PlaySoundEvent(null,thunder);io.github.astelev.around_planet.client.SpaceWeatherSounds.play(weather);require(weather.getSound()==null,"Thunder audible in space");
        var engine=new net.neoforged.neoforge.client.event.sound.PlaySoundEvent(null,click);io.github.astelev.around_planet.client.SpaceWeatherSounds.play(engine);require(engine.getSound()==click,"Space muted unrelated sounds");
        var view=SpaceCells.get(mc.getSingleplayerServer().overworld()).all();try{SpaceCells.view(mc.level,List.of());var surface=new net.neoforged.neoforge.client.event.sound.PlaySoundEvent(null,thunder);io.github.astelev.around_planet.client.SpaceWeatherSounds.play(surface);require(surface.getSound()==thunder,"Space muted surface weather");}finally{SpaceCells.view(mc.level,view);}
        io.github.astelev.around_planet.AroundPlanet.LOGGER.info("SPACE_WEATHER_SOUNDS PASS thunder suppressed in space, surface and other sounds preserved");
    }
    private static void use(ServerSubLevel ship){var level=ship.getLevel();var p=level.players().getFirst();level.getBlockState(block).useWithoutItem(level,p,new BlockHitResult(Vec3.atCenterOf(block),Direction.UP,block,false));}
    private static void clickOrbit(OrbitMapScreen screen){try{var visible=OrbitMapScreen.class.getDeclaredMethod("visible",SpaceVector.class);visible.setAccessible(true);var p=ManeuverClient.current();var curve=OrbitPlot.create(p.trajectory().at(ManeuverClient.now()),p.trajectory().mu(),SpaceHud.current().radius(),SpaceHud.current().returnAltitude(),false);for(double f:new double[]{.48,.45,.58,.32,.7,.85}){var point=p.trajectory().at(ManeuverClient.now()+(long)(curve.period()*20*f)).position();if(!(Boolean)visible.invoke(screen,point))continue;var xy=project(screen,point);screen.mouseClicked(xy.x(),xy.y(),0);screen.mouseReleased(xy.x(),xy.y(),0);return;}throw new AssertionError("No visible orbit hit target");}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
